import base64,json,pathlib,tempfile,subprocess,sys,shlex
files={'setup37.py': '"""Create only a new empty sample folder; refuse every existing path."""\nfrom pathlib import Path\nimport stat\n\ndef make(path):\n    root = Path(path).absolute()\n    if \'..\' in root.parts:\n        raise OSError(\'Parent-traversal paths are unsupported.\')\n    for parent in reversed(root.parents):\n        info = parent.lstat()\n        if stat.S_ISLNK(info.st_mode) or getattr(info, \'st_file_attributes\', 0) & 0x400:\n            raise OSError(\'Linked/reparse-point parents are unsupported.\')\n    Path(path).mkdir()\n\nif __name__ == \'__main__\':\n    try:\n        make(Path(__file__).absolute().parent / \'sample\')\n    except FileExistsError:\n        raise SystemExit(\'Stopped: sample already exists. Nothing was replaced or deleted.\')\n    print(\'Created new empty sample folder.\')\n', 'check37.py': '"""Limited checks for this generated fixture, not arbitrary footage or playback."""\nimport array\nimport hashlib\nimport json\nimport math\nimport subprocess\nimport sys\nimport stat\nfrom pathlib import Path\n\n\ndef safe_input(value, directory=False):\n    path = Path(value).absolute()\n    if \'..\' in path.parts:\n        raise OSError(\'Parent-traversal paths are unsupported.\')\n    for part in [*reversed(path.parents), path]:\n        info = part.lstat()\n        if stat.S_ISLNK(info.st_mode) or getattr(info, \'st_file_attributes\', 0) & 0x400:\n            raise OSError(\'Links/reparse points are unsupported.\')\n    info = path.lstat()\n    if directory:\n        if not stat.S_ISDIR(info.st_mode):\n            raise NotADirectoryError(\'Expected an ordinary directory.\')\n    elif not stat.S_ISREG(info.st_mode) or info.st_nlink != 1:\n        raise OSError(\'Expected an ordinary singly linked file.\')\n    return path\n\n\ndef digest(path):\n    h = hashlib.sha256()\n    with safe_input(path).open(\'rb\') as handle:\n        for chunk in iter(lambda: handle.read(1024 * 1024), b\'\'):\n            h.update(chunk)\n    return h.hexdigest()\n\n\ndef probe(path):\n    safe_input(path)\n    result = subprocess.run([\'ffprobe\', \'-v\', \'error\', \'-show_entries\',\n        \'stream=codec_type,codec_name,pix_fmt:format=duration,size\', \'-of\', \'json\', str(path)],\n        capture_output=True, text=True, check=True)\n    return json.loads(result.stdout)\n\n\ndef check(root):\n    root = safe_input(root, directory=True)\n    original = root / \'input.mp4\'\n    smaller = root / \'small.mp4\'\n    assert digest(original) == safe_input(root / \'input.sha256\').read_text().strip(), \'Input changed\'\n    info = probe(smaller)\n    streams = info[\'streams\']\n    assert any(x[\'codec_type\'] == \'video\' and x[\'codec_name\'] == \'h264\' and x[\'pix_fmt\'] == \'yuv420p\' for x in streams), \'Expected video missing\'\n    assert any(x[\'codec_type\'] == \'audio\' and x[\'codec_name\'] == \'aac\' for x in streams), \'Expected audio missing\'\n    assert 2.9 < float(info[\'format\'][\'duration\']) < 3.2, \'Unexpected fixture duration\'\n    assert smaller.stat().st_size < original.stat().st_size, \'This fixture did not get smaller\'\n    decoded = subprocess.run([\'ffmpeg\', \'-v\', \'error\', \'-i\', str(smaller), \'-map\', \'0:v:0\',\n        \'-map\', \'0:a:0\', \'-f\', \'null\', \'-\'], capture_output=True, check=True)\n    assert not decoded.stderr.strip(), \'Decoder reported an error\'\n    audio = subprocess.run([\'ffmpeg\', \'-v\', \'error\', \'-i\', str(smaller), \'-vn\', \'-ac\', \'1\',\n        \'-ar\', \'8000\', \'-f\', \'s16le\', \'-\'], capture_output=True, check=True)\n    assert not audio.stderr.strip(), \'Audio decoder reported an error\'\n    pcm = audio.stdout\n    values = array.array(\'h\')\n    values.frombytes(pcm)\n    if sys.byteorder != \'little\':\n        values.byteswap()\n    assert len(values) > 22000, \'Too few decoded audio samples\'\n    rms = math.sqrt(sum(v*v for v in values) / len(values))\n    assert rms > 100, \'Tone is absent or too quiet for this fixture\'\n    print(\'PASS: source SHA256 unchanged; H.264/yuv420p and AAC present; fixture duration near 3 seconds.\')\n    print(\'PASS: output smaller for this fixture; both streams decoded; decoded tone RMS exceeds 100.\')\n    print(\'These checks do not prove audio meaning, visual quality or playback on a phone. Watch and listen before sharing.\')\n\n\ndef main(argv):\n    if argv not in ([\'snapshot\'], [\'verify\']):\n        print(\'Usage: python check37.py snapshot|verify\', file=sys.stderr)\n        return 2\n    try:\n        root = safe_input(Path(__file__).absolute().parent / \'sample\', directory=True)\n        if argv == [\'snapshot\']:\n            manifest = root / \'input.sha256\'\n            try:\n                manifest.lstat()\n            except FileNotFoundError:\n                pass\n            else:\n                raise FileExistsError(manifest)\n            with manifest.open(\'x\', encoding=\'ascii\') as handle:\n                handle.write(digest(root / \'input.mp4\') + \'\\n\')\n            print(\'Saved input digest in a new input.sha256 file; existing manifests are refused.\')\n        else:\n            check(root)\n    except (OSError, subprocess.SubprocessError, ValueError, AssertionError) as error:\n        print(\'Stopped: \' + str(error), file=sys.stderr)\n        return 2\n    return 0\n\n\nif __name__ == \'__main__\':\n    sys.exit(main(sys.argv[1:]))\n', 'test_lesson37.py': '"""Small temporary-fixture checks; no production footage or device tests."""\nfrom unittest import mock\nimport os\nimport contextlib\nimport io\nimport shutil\nimport subprocess\nimport tempfile\nimport unittest\nfrom pathlib import Path\nimport check37\nimport setup37\n\nGEN = [\'ffmpeg\',\'-n\',\'-hide_banner\',\'-nostats\',\'-v\',\'error\',\'-f\',\'lavfi\',\'-i\',\n       \'testsrc=duration=3:size=640x360:rate=24\',\'-f\',\'lavfi\',\'-i\',\n       \'sine=frequency=1000:duration=3\',\'-map\',\'0:v:0\',\'-map\',\'1:a:0\',\n       \'-c:v\',\'libx264\',\'-threads\',\'1\',\'-crf\',\'18\',\'-pix_fmt\',\'yuv420p\',\'-c:a\',\'aac\',\'-b:a\',\'64k\',\'-shortest\']\nSHRINK = [\'ffmpeg\',\'-n\',\'-hide_banner\',\'-nostats\',\'-v\',\'error\',\'-i\',\'input.mp4\',\n          \'-map\',\'0:v:0\',\'-map\',\'0:a:0\',\'-c:v\',\'libx264\',\'-threads\',\'1\',\'-crf\',\'28\',\n          \'-pix_fmt\',\'yuv420p\',\'-c:a\',\'aac\',\'-b:a\',\'64k\']\n\nclass FixtureTests(unittest.TestCase):\n    @classmethod\n    def setUpClass(cls):\n        cls.temp = tempfile.TemporaryDirectory()\n        cls.root = Path(cls.temp.name)\n        subprocess.run(GEN + [\'input.mp4\'],cwd=cls.root,capture_output=True,check=True)\n        (cls.root/\'input.sha256\').write_text(check37.digest(cls.root/\'input.mp4\')+\'\\n\')\n        subprocess.run(SHRINK + [\'small.mp4\'],cwd=cls.root,capture_output=True,check=True)\n    @classmethod\n    def tearDownClass(cls): cls.temp.cleanup()\n    def test_new_setup(self):\n        with tempfile.TemporaryDirectory() as d:\n            target=Path(d)/\'sample\';setup37.make(target);self.assertEqual(list(target.iterdir()),[])\n    def test_existing_folder_preserves_nested_data(self):\n        with tempfile.TemporaryDirectory() as d:\n            root=Path(d)/\'sample\';(root/\'nested\').mkdir(parents=True);p=root/\'nested\'/\'keep\';p.write_bytes(b\'KEEP\');before=(p.read_bytes(),p.stat().st_mtime_ns)\n            with self.assertRaises(FileExistsError):setup37.make(root)\n            self.assertEqual(before,(p.read_bytes(),p.stat().st_mtime_ns))\n    def test_existing_file_preserved(self):\n        with tempfile.TemporaryDirectory() as d:\n            p=Path(d)/\'sample\';p.write_bytes(b\'KEEP\')\n            with self.assertRaises(FileExistsError):setup37.make(p)\n            self.assertEqual(p.read_bytes(),b\'KEEP\')\n    def test_fixture_checks(self):\n        with contextlib.redirect_stdout(io.StringIO()):check37.check(self.root)\n    def test_reencode_preserves_input_bytes_and_mtime(self):\n        p=self.root/\'input.mp4\';before=(check37.digest(p),p.stat().st_mtime_ns)\n        subprocess.run(SHRINK+[\'extra.mp4\'],cwd=self.root,capture_output=True,check=True)\n        self.assertEqual(before,(check37.digest(p),p.stat().st_mtime_ns))\n    def test_existing_output_preserved(self):\n        p=self.root/\'old.mp4\';p.write_bytes(b\'KEEP\');before=(p.read_bytes(),p.stat().st_mtime_ns)\n        result=subprocess.run(SHRINK+[\'old.mp4\'],cwd=self.root,capture_output=True)\n        self.assertIn(b\'already exists\', result.stderr);self.assertEqual(before,(p.read_bytes(),p.stat().st_mtime_ns))\n    def test_empty_existing_output_preserved(self):\n        p=self.root/\'empty.mp4\';p.touch();before=p.stat().st_mtime_ns\n        result=subprocess.run(SHRINK+[\'empty.mp4\'],cwd=self.root,capture_output=True)\n        self.assertIn(b\'already exists\', result.stderr);self.assertEqual(p.read_bytes(),b\'\');self.assertEqual(before,p.stat().st_mtime_ns)\n    def test_audio_extraction_has_no_video(self):\n        subprocess.run([\'ffmpeg\',\'-n\',\'-v\',\'error\',\'-i\',\'input.mp4\',\'-vn\',\'-c:a\',\'copy\',\'tone.aac\'],cwd=self.root,capture_output=True,check=True)\n        info=check37.probe(self.root/\'tone.aac\');self.assertTrue(info[\'streams\']);self.assertTrue(all(x[\'codec_type\']==\'audio\' for x in info[\'streams\']))\n    def test_missing_input_is_failure(self):\n        result=subprocess.run([\'ffmpeg\',\'-n\',\'-v\',\'error\',\'-i\',\'missing.mp4\',\'absent.mp4\'],cwd=self.root,capture_output=True)\n        self.assertTrue(result.stderr.strip());self.assertFalse((self.root/\'absent.mp4\').exists())\n    def test_snapshot_refuses_existing_manifest(self):\n        import sys\n        with tempfile.TemporaryDirectory() as d:\n            r=Path(d);shutil.copyfile(Path(check37.__file__),r/\'check37.py\');(r/\'sample\').mkdir();(r/\'sample\'/\'input.mp4\').write_bytes(b\'input\');p=r/\'sample\'/\'input.sha256\';p.write_bytes(b\'KEEP\');before=(p.read_bytes(),p.stat().st_mtime_ns)\n            result=subprocess.run([sys.executable,str(r/\'check37.py\'),\'snapshot\'],capture_output=True)\n            self.assertNotEqual(result.returncode,0);self.assertEqual(before,(p.read_bytes(),p.stat().st_mtime_ns))\n    def test_audio_extraction_refuses_existing_output(self):\n        p=self.root/\'old.aac\';p.write_bytes(b\'KEEP\');before=(p.read_bytes(),p.stat().st_mtime_ns)\n        result=subprocess.run([\'ffmpeg\',\'-n\',\'-v\',\'error\',\'-i\',\'input.mp4\',\'-vn\',\'-c:a\',\'copy\',\'old.aac\'],cwd=self.root,capture_output=True)\n        self.assertIn(b\'already exists\', result.stderr);self.assertEqual(before,(p.read_bytes(),p.stat().st_mtime_ns))\n    def test_changed_input_digest_is_detected(self):\n        with tempfile.TemporaryDirectory() as d:\n            r=Path(d)\n            for name in [\'input.mp4\',\'small.mp4\',\'input.sha256\']:shutil.copyfile(self.root/name,r/name)\n            with (r/\'input.mp4\').open(\'ab\') as h:h.write(b\'change\')\n            with self.assertRaisesRegex(AssertionError,\'Input changed\'):check37.check(r)\n\nclass PathSafety(unittest.TestCase):\n    def setUp(self):\n        self.tmp=tempfile.TemporaryDirectory();self.addCleanup(self.tmp.cleanup)\n        self.base=Path(self.tmp.name);self.root=self.base/\'tree\';self.root.mkdir()\n        self.file=self.root/\'zero\';self.file.write_bytes(b\'\')\n    def link(self,path,target,directory=False):\n        try:path.symlink_to(target,target_is_directory=directory)\n        except OSError:self.skipTest(\'Symlinks unavailable\')\n    def code(self,path):\n        try:check37.digest(path)\n        except OSError:return 2\n        return 0\n    def test_root_alias_refuses(self):\n        p=self.base/\'alias\';self.link(p,self.root,True);self.assertEqual(self.code(p),2)\n    def test_ancestor_alias_refuses(self):\n        p=self.base/\'alias\';self.link(p,self.base,True);self.assertEqual(self.code(p/\'tree\'),2)\n    def test_file_alias_refuses(self):\n        p=self.base/\'linked\';self.link(p,self.file);self.assertEqual(self.code(p),2)\n    def test_file_hardlink_refuses(self):\n        p=self.base/\'hard\';os.link(self.file,p);self.assertEqual(self.code(p),2)\n    def test_file_pipe_refuses(self):\n        if not hasattr(os,\'mkfifo\'):self.skipTest(\'Unix pipe unavailable\')\n        p=self.base/\'pipe\';os.mkfifo(p);self.assertEqual(self.code(p),2)\n    def test_file_self_loop_refuses(self):\n        p=self.base/\'loop\';self.link(p,p);self.assertEqual(self.code(p),2)\n    def test_file_dangling_refuses(self):\n        p=self.base/\'alias\';self.link(p,self.base/\'missing\');self.assertEqual(self.code(p),2)\n    def test_file_traversal_refuses(self):self.assertEqual(self.code(self.root/\'..\'/\'tree\'/\'zero\'),2)\n    def test_file_ancestor_refuses(self):\n        p=self.base/\'alias\';self.link(p,self.root,True);self.assertEqual(self.code(p/\'zero\'),2)\n    def test_metadata_error_refuses(self):\n        with mock.patch.object(Path,\'lstat\',side_effect=OSError(\'forced\')):self.assertEqual(self.code(self.file),2)\n    def test_reparse_attribute_refuses(self):\n        real=Path.lstat\n        def fake(p,*a,**kw):\n            value=real(p,*a,**kw)\n            if p==self.file:return type(\'Reparse\',(),{\'st_mode\':value.st_mode,\'st_file_attributes\':0x400})()\n            return value\n        with mock.patch.object(Path,\'lstat\',fake):self.assertEqual(self.code(self.file),2)\n\n\n    def test_read_error_stops(self):\n        with mock.patch.object(Path,\'open\',side_effect=OSError(\'forced\')):\n            self.assertEqual(self.code(self.file),2)\n    def test_probe_alias_refuses_before_subprocess(self):\n        p=self.base/\'linked\';self.link(p,self.file)\n        with mock.patch.object(subprocess,\'run\') as run:\n            with self.assertRaises(OSError):check37.probe(p)\n            run.assert_not_called()\n    def test_setup_alias_parent_refuses(self):\n        p=self.base/\'alias\';self.link(p,self.root,True)\n        with self.assertRaises(OSError):setup37.make(p/\'new\')\n        self.assertFalse((self.root/\'new\').exists())\n    def test_setup_traversal_refuses(self):\n        with self.assertRaises(OSError):setup37.make(self.root/\'..\'/\'new\')\n    def test_cli_read_error_nonzero(self):\n        with mock.patch.object(Path,\'lstat\',side_effect=OSError(\'forced\')),contextlib.redirect_stderr(io.StringIO()):\n            self.assertEqual(check37.main([\'verify\']),2)\n\n\nif __name__==\'__main__\':unittest.main()\n'}
